static std::string sha(const std::string&s){unsigned char d[SHA256_DIGEST_LENGTH];SHA256((const unsigned char*)s.data(),s.size(),d);std::ostringstream q;for(auto c:d)q<<std::hex<<std::setw(2)<<std::setfill('0')<<(int)c;return q.str();}
static O&obj(V&v){if(!std::holds_alternative<O>(v.x))throw Err("INVALID_SCHEMA");return std::get<O>(v.x);}static const O&obj(const V&v){if(!std::holds_alternative<O>(v.x))throw Err("INVALID_SCHEMA");return std::get<O>(v.x);}static std::string ss(const O&o,const char*k){auto it=o.find(k);if(it==o.end()||!std::holds_alternative<std::string>(it->second.x))throw Err("INVALID_SCHEMA");return std::get<std::string>(it->second.x);}static int64_t ii(const O&o,const char*k){auto it=o.find(k);if(it==o.end()||!std::holds_alternative<int64_t>(it->second.x))throw Err("INVALID_SCHEMA");return std::get<int64_t>(it->second.x);}static void ver(const O&o){auto it=o.find("wire_profile_version");if(it==o.end()||!std::holds_alternative<int64_t>(it->second.x))throw Err("INVALID_SCHEMA");if(std::get<int64_t>(it->second.x)!=1)throw Err("UNSUPPORTED_VERSION");}
static bool leap(int y){return y%4==0&&(y%100!=0||y%400==0);}static void timev(const V&v){if(std::holds_alternative<std::nullptr_t>(v.x))return;if(!std::holds_alternative<std::string>(v.x))throw Err("INVALID_SCHEMA");auto s=std::get<std::string>(v.x);if(s.size()<20||s[4]!='-'||s[7]!='-'||s[10]!='T'||s[13]!=':'||s[16]!=':'||s.back()!='Z')throw Err("INVALID_SCHEMA");auto num=[&](int p,int n){for(int j=0;j<n;j++)if(!isdigit((unsigned char)s[p+j]))throw Err("INVALID_SCHEMA");return std::stoi(s.substr(p,n));};int y=num(0,4),m=num(5,2),d=num(8,2),h=num(11,2),mi=num(14,2),se=num(17,2);int dm[]={0,31,28,31,30,31,30,31,31,30,31,30,31};if(m<1||m>12)throw Err("INVALID_SCHEMA");if(m==2&&leap(y))dm[2]=29;if(d<1||d>dm[m]||h>23||mi>59||se>59)throw Err("INVALID_SCHEMA");if(s.size()>20){if(s[19]!='.')throw Err("INVALID_SCHEMA");size_t n=s.size()-21;if(n<1||n>9)throw Err("INVALID_SCHEMA");for(size_t j=20;j<s.size()-1;j++)if(!isdigit((unsigned char)s[j]))throw Err("INVALID_SCHEMA");if(s[s.size()-2]=='0')throw Err("INVALID_SCHEMA");}}
static void ident(const std::string&s){if(s.empty()||s.size()>255||nfc(s)!=s)throw Err("INVALID_SCHEMA");for(unsigned char c:s)if(c<32)throw Err("INVALID_SCHEMA");}
static void closed(const O&o,std::initializer_list<const char*>ks){std::set<std::string>a;for(auto k:ks)a.insert(k);for(auto&[k,v]:o)if(!a.count(k))throw Err("UNSUPPORTED_REQUIRED_FIELD");for(auto k:a)if(!o.count(k))throw Err("INVALID_SCHEMA");}
