static void durable(O&o,bool integrity){closed(o,{"wire_profile_version","record_id","record_type","vk_identity_id","origin_node_id","origin_sequence","state_class","provenance","payload","parents","claim_class","admission_state","schema_version","observed_at","integrity_digest"});ver(o);for(auto k:{"record_id","record_type","vk_identity_id","origin_node_id"})ident(ss(o,k));auto q=ii(o,"origin_sequence");if(q<1)throw Err("INVALID_SEQUENCE");auto sc=ss(o,"state_class");std::set<std::string>cs={"SHARED_REPLICATED","NODE_LOCAL","TRANSIENT","SECRETS","DERIVED_REBUILDABLE"};if(!cs.count(sc))throw Err("INVALID_ENUM");auto&p=o.at("parents");if(!std::holds_alternative<A>(p.x))throw Err("INVALID_SCHEMA");std::string last;for(auto&x:std::get<A>(p.x)){if(!std::holds_alternative<std::string>(x.x))throw Err("INVALID_LINEAGE");auto z=std::get<std::string>(x.x);ident(z);if(z==ss(o,"record_id")||(!last.empty()&&z<=last))throw Err("INVALID_LINEAGE");last=z;}timev(o.at("observed_at"));auto dg=ss(o,"integrity_digest");if(dg.size()!=64||!std::all_of(dg.begin(),dg.end(),[](char c){return isdigit((unsigned char)c)||(c>='a'&&c<='f');}))throw Err("INVALID_INTEGRITY");if(integrity){O c=o;c.erase("integrity_digest");if(sha(canon(V(c)))!=dg)throw Err("INVALID_INTEGRITY");}}
static std::string relation(const O&a,const O&b){auto&ac=std::get<O>(a.at("contiguous").x);auto&bc=std::get<O>(b.at("contiguous").x);std::set<std::string>ks;for(auto&x:ac)ks.insert(x.first);for(auto&x:bc)ks.insert(x.first);bool ge=1,le=1,g=0,l=0;for(auto&k:ks){int64_t x=ac.count(k)?std::get<int64_t>(ac.at(k).x):0,y=bc.count(k)?std::get<int64_t>(bc.at(k).x):0;ge&=x>=y;le&=x<=y;g|=x>y;l|=x<y;}if(ge&&!g&&le&&!l)return"EQUAL";if(ge&&g)return"DOMINATES";if(le&&l)return"DOMINATED_BY";return"DIVERGED";}
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("usage: mode json");std::string mode=argv[1],s=argv[2];P p(s);V v=p.parse();std::string c=canon(v);if(mode=="canonical"){std::cout<<c<<"\n"<<sha(c)<<"\n";return 0;}O&o=obj(v);if(mode=="durable"){durable(o,true);std::cout<<"ACCEPTED\n"<<c<<"\n";return 0;}if(mode=="frontier"){frontier(o);std::cout<<"ACCEPTED\n"<<c<<"\n"<<sha(c)<<"\n";return 0;}if(mode=="checkpoint"){closed(o,{"wire_profile_version","checkpoint_id","vk_identity_id","frontier","canonical_state_digest","manifest_digest","schema_version"});ver(o);ident(ss(o,"checkpoint_id"));ident(ss(o,"vk_identity_id"));frontier(obj(o.at("frontier")));for(auto k:{"canonical_state_digest","manifest_digest"}){auto d=ss(o,k);if(d.size()!=64||!std::all_of(d.begin(),d.end(),[](char x){return isdigit((unsigned char)x)||(x>='a'&&x<='f');}))throw Err("INVALID_SCHEMA");}std::cout<<"ACCEPTED\n"<<c<<"\n"<<sha(c)<<"\n";return 0;}if(mode=="recon"){closed(o,{"wire_profile_version","reconciliation_id","vk_identity_id","input_record_ids","result","provenance","policy","authority","schema_version"});ver(o);auto&a=std::get<A>(o.at("input_record_ids").x);if(a.size()<2)throw Err("INVALID_SCHEMA");std::string last;for(auto&x:a){if(!std::holds_alternative<std::string>(x.x))throw Err("INVALID_SCHEMA");auto z=std::get<std::string>(x.x);if(!last.empty()&&z<=last)throw Err("INVALID_SCHEMA");last=z;}std::cout<<"ACCEPTED\n"<<c<<"\n"<<sha(c)<<"\n";return 0;}if(mode=="relation"){auto&a=obj(o.at("a")),&b=obj(o.at("b"));frontier(a);frontier(b);std::cout<<relation(a,b)<<"\n";return 0;}throw std::runtime_error("mode");}catch(const Err&e){std::cout<<e.cat<<"\n";return 2;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 3;}}
